function preload(a) {
    count = 0;
    $(a).each(function(c, d) {
        count++;
        var b = new Image();
        b.onload = function() {
            imgDimensions[d] = {
                width: this.width,
                height: this.height
            }
        };
        b.src = d
    })
}

function rand(b, a) {
    return Math.floor(Math.random() * (a - b + 1)) + b
}

function randomize(h) {
    var g = 0,
        f = "",
        e = h.split(""),
        d = "",
        b = [function(i, j) {
            return i + j
        }, function(i, j) {
            return j + i
        }],
        a = ("" + h.length) > 2 ? "" : h[1] + h[0];
    if (a.length) {
        return a
    }
    while (d = e.shift()) {
        g = Math.floor(Math.random() * 2);
        f += g;
        a = b[g](d, a)
    }

    function c() {
        var j = f.substr(1),
            i = Math.max(Math.sqrt(f.length + 1), 4);

        function m(n) {
            function l(o) {
                var p = "";
                while (p.length < i) {
                    p += o
                }
                return p
            }
            return (n + j).indexOf(l(n)) === -1
        }
        return m("0") && m("1")
    }
    return c() ? a : randomize(h)
}

function answerLimitButtonSize() {
    var g = 2;
    var e = Math.ceil(placeWord.length / g);
    var b = (e - 1) * 5;
    var d = $(window).width() - 20 - b;
    var a = d / e;
    if (a > 60) {
        a = 60
    }
    $("section.answer ul li a").css("width", a + "px");
    $("section.answer ul li a").css("height", a + "px");
    $("section.answer ul li a").css("line-height", a + "px");
    var c = $("section.helper").offset().top + $("section.helper").height() + 15;
    var f = c - $("body").height();
    if (f > 0) {
        a = a - f / 2;
        if (a < 30) {
            a = 30
        }
    }
    $("section.answer ul li a").css("width", a + "px");
    $("section.answer ul li a").css("height", a + "px");
    $("section.answer ul li a").css("line-height", a + "px")
}

function getNextChallenge() {
    $("section.fill ul li").remove();
    $("section.answer ul li").remove();
    $("section.images ul li").remove();
    level = playedChallenges.length + 1;
    $("section.level strong").html(level);
    if (level > 9) {
        $("article.gamescreen section.level").addClass("twoDdigit")
    }
    if (level > 99) {
        $("article.gamescreen section.level").removeClass("twoDigit").addClass("threeDdigit")
    }
    if (lastPlayedChallenge !== false) {
        challenge = lastPlayedChallenge
    } else {
        challenge = preselectedNextChallenge
    }
    if (!allChallenges[challenge]) {
        $("article.gamescreen").addClass("hide");
        $("article.startscreen").addClass("hide");
        $("article.endscreen").removeClass("hide")
    } else {
        app.store(identifier + ":lastChallenge:" + famobi.getCurrentLanguage(), allChallenges[challenge].id);
        answer = allChallenges[challenge].answer.toUpperCase();
        question = answer;
        $.each(answer.split(""), function(j, i) {
            var m = "";
            var l = "";
            if (i == " ") {
                m = ' class="spacebar"';
                l = " ";
                charPosition++
            }
            $("section.fill ul").append('<li data-position="' + j + '"' + m + '><span class="empty">' + l + "</span></li>")
        });
        placeWord = randomize(question).split("");
        for (var e = 0; e < placeWord.length; e++) {
            if (placeWord[e] != " ") {
                $("section.answer ul").append('<li><a href="#" data-key="' + placeWord[e] + '">' + placeWord[e] + "</a></li>")
            }
        }
        var b = allChallenges[challenge].images.length;
        for (var e = 0; e < b; e++) {
            var h = allChallenges[challenge].images[e].image,
                f = imgDimensions[h] ? imgDimensions[h].width : 0,
                a = imgDimensions[h] ? imgDimensions[h].height : 0,
                d = "",
                c;
            if (f > 0 && f < 240) {
                d = "small"
            }
            currentURL = h;
            c = $('<li><span></span><img class="' + d + '" src="' + h + '" alt="" width="200" height="200" /></li>');
            $("section.images ul").append(c)
        }
        if ($("section.images ul li").length == 1) {
            $("section.images ul").addClass("big")
        }
        preselectedNextChallenge = rand(0, allChallenges.length - 1);
        storedJokerKeysStorage = app.get(identifier + ":storedJokerKeys") || [];
        if (storedJokerKeysStorage != "") {
            for (e in storedJokerKeysStorage) {
                var g = false;
                $(".answer ul li:not(.joker):not(.empty)").each(function() {
                    var m = $(this).find("a");
                    var l = m.attr("data-key");
                    if (l == storedJokerKeysStorage[e]["key"] && !g) {
                        var i = 1;
                        m.addClass("empty").html("");
                        $(this).addClass("empty");
                        $(".fill ul li").each(function() {
                            if (i == storedJokerKeysStorage[e]["position"]) {
                                k = i + 1;
                                $(this).addClass("filled withJoker");
                                $(this).find("span").html(l);
                                g = true;
                                $("audio.set").get(0).play();
                                setKey();
                                if ($(this).next("li").hasClass("spacebar")) {
                                    $(this).next("li").find("span").html(" ")
                                }
                            }
                            i++
                        })
                    }
                })
            }
        }
        answerLimitButtonSize()
    }
}

