function getXmlContent() {
    totalChallenges = 0;
    lastPlayedChallenge = false;
    $.ajax({
        type: "GET",
        url: window.famobi.__("challengesXml"),
        dataType: "xml",
        success: function(a) {
            allChallenges = [];
            parsedChallenge = 0;
            var c = $(a).find("challenge");
            c.each(function(e, d) {
                var h = $(this).attr("id");
                var f = $(this).find("answer").text();
                if (!h) {
                    h = md5(f);
                    $(this).attr("id", h)
                }
                if ($.inArray(f.toUpperCase(), playedChallenges) < 0) {
                    totalChallenges++;
                    allChallenges[parsedChallenge] = new Array();
                    images = new Array();
                    $(this).find("images").each(function() {
                        $(this).find("image").each(function() {
                            var i = $(this).text();
                            images.push({
                                image: i
                            })
                        })
                    });
                    allChallenges[parsedChallenge].images = images;
                    allChallenges[parsedChallenge].answer = f;
                    allChallenges[parsedChallenge].id = h;
                    var g = famobi.getUrlParams()["id"];
                    if (g) {
                        if (h == g) {
                            lastPlayedChallenge = parsedChallenge
                        }
                    } else {
                        if (h == lastChallenge) {
                            lastPlayedChallenge = parsedChallenge
                        }
                    }
                    parsedChallenge++
                } else {}
            });
            preselectedNextChallenge = rand(0, allChallenges.length - 1);
            if (lastPlayedChallenge !== false) {
                preselectedNextChallenge = lastPlayedChallenge
            }
            if (allChallenges[preselectedNextChallenge]) {
                for (var b = 0; b < allChallenges[preselectedNextChallenge].images.length; b++) {
                    preloadImages.push(allChallenges[preselectedNextChallenge].images[b].image)
                }
                preload(preloadImages)
            }
            if (famobi.getUrlParams()["id"] !== undefined) {
                setTimeout(function() {
                    $("article.startscreen").addClass("hide");
                    $("article.gamescreen").removeClass("hide");
                    getNextChallenge()
                }, 250)
            }
        }
    })
}
