jQuery(window).on("keypress", function(b) {
    var a = String.fromCharCode(b.which).toUpperCase();
    jQuery("[data-key='" + a + "']:not(.empty):first").trigger("click")
});
jQuery(window).on("keydown", function(b) {
    var a = (b.which === 8);
    if (a) {
        $("[data-position].filled:last").trigger("click");
        b.cancelBubble = false;
        b.returnValue = false;
        b.preventDefault();
        return false
    }
});

function clearFill() {
    $("section.fill ul").removeClass("wrong");
    $("section.fill ul li.clear").remove();
    $("audio.delete").get(0).play();
    $("section.fill ul li").each(function() {
        var a = $(this).find("span").html();
        if (!$(this).hasClass("withJoker")) {
            $('[data-key="' + a + '"].empty:first').html(a).removeClass("empty");
            $("[data-position].filled:last").addClass("last");
            if (!$(this).hasClass("spacebar")) {
                charPosition--;
                $(this).removeClass("filled last").find("span").html("")
            } else {}
        } else {}
    })
}

function debugOutput(a) {
    $("#output").html($("#output").html() + "\n" + a)
}

function setKey() {
    charPosition++;
    var c = "";
    $("section.fill ul li").each(function() {
        c = c + $(this).find("span").html()
    });
    if (charPosition == answer.length) {
        if (c.toUpperCase() == answer.toUpperCase()) {
            charPosition = 0;
            playedChallenges.push(answer);
            app.store(identifier + ":playedChallenges:" + famobi.getCurrentLanguage(), playedChallenges);
            allChallenges.splice(challenge, 1);
            preselectedNextChallenge = rand(0, allChallenges.length - 1);
            if (lastPlayedChallenge !== false) {
                preselectedNextChallenge = lastPlayedChallenge
            }
            if (allChallenges[preselectedNextChallenge]) {
                for (var a = 0; a < allChallenges[preselectedNextChallenge].images.length; a++) {
                    preloadImages.push(allChallenges[preselectedNextChallenge].images[a].image)
                }
                preload(preloadImages)
            }
            app.store(identifier + ":lastChallenge:" + famobi.getCurrentLanguage(), "");
            lastPlayedChallenge = false;
            var b = rand(0, motivationTextes.length - 1);
            $("body").attr("data-overlay-text", motivationTextes[b]);
            $("body").addClass("overlay");
            app.store(identifier + ":storedJokerKeys", "");
            storeJokerKeys = {};
            setTimeout(function() {
                $("body").addClass("slideIn");
                $("audio.levelPassed").get(0).play()
            }, 250);
            setTimeout(function() {
                $("body").removeClass("slideIn");
                setTimeout(function() {
                    $("body").removeClass("overlay");
                    try {
                        window.famobi.submitHighscore("", level)
                    } catch (d) {}
                    getNextChallenge()
                }, 250)
            }, 3000)
        } else {
            $("audio.fail").get(0).play();
            $("section.fill ul").addClass("wrong");
            $("section.fill ul li:not(.ask):last").after('<li class="clear"><span>X</span></li>')
        }
    }
}

function getRandomKeyToPlace() {
    var d = [];
    var f = 1;
    var a = 1;
    $(".answer ul li:not(.joker)").each(function() {
        if (!$(this).find("a").hasClass("empty")) {
            d[f] = a;
            f++
        }
        a++
    });
    var c = rand(1, d.length - 1);
    var e = d[c];
    var b = 1;
    $(".answer ul li:not(.joker)").each(function() {
        if (b == e) {
            var l = $(this).find("a");
            var h = l.attr("data-key");
            var i = false;
            var g = 0;
            $(".fill ul li").each(function() {
                if (answer[g] == h && !i && !$(this).hasClass("filled")) {
                    l.addClass("empty").html("");
                    k = g + 1;
                    storeJokerKeys[g] = {
                        key: h,
                        position: k
                    };
                    $(this).addClass("filled withJoker");
                    $(this).find("span").html(h);
                    i = true;
                    $("audio.setJoker").get(0).play();
                    setKey();
                    app.get(identifier + ":joker");
                    numJokers--;
                    app.store(identifier + ":joker", numJokers);
                    $('[data-type="joker"]').find("em").html(numJokers);
                    if (numJokers == 0 && !isPhonegap) {
                        $('[data-type="joker"]').addClass("addJokers");
                        var m = new Date().getTime();
                        lastGotJokersTs = app.get(identifier + ":lastGotJokersTs") || 0;
                        var n = m - lastGotJokersTs;
                        var p = getJokerTimeout - n;
                        var j = Math.round(p / 1000);
                        if (n < getJokerTimeout) {
                            $('[data-type="joker"]').addClass("disabled");
                            jokerCountdownTimer = j;

                            function o() {
                                setTimeout(function() {
                                    var q = new Date().getTime();
                                    lastGotJokersTs = app.get(identifier + ":lastGotJokersTs") || 0;
                                    var r = q - lastGotJokersTs;
                                    var s = getJokerTimeout - r;
                                    jokerCountdownTimestamp = s;
                                    jokerCountdownTimestamp = jokerCountdownTimestamp - 1000;
                                    if (jokerCountdownTimestamp > 0) {
                                        $('[data-type="joker"] .addJokers em').removeClass("hide").html(Math.round(jokerCountdownTimestamp / 1000));
                                        o()
                                    } else {
                                        $('[data-type="joker"] .addJokers em').addClass("hide");
                                        $('[data-type="joker"]').removeClass("disabled")
                                    }
                                }, 1000)
                            }
                            o()
                        }
                    }
                }
                g++
            })
        }
        b++
    });
    app.store(identifier + ":storedJokerKeys", storeJokerKeys)
}
